import { test, expect } from '@playwright/test';

const BASE = process.env.WI_BASE_URL || "http://127.0.0.1:8765";
const resolveURL = (value: string) => /^https?:\/\//i.test(value)
  ? value
  : `${BASE.replace(/\/$/, '')}/${value.replace(/^\//, '')}`;

test("gushi-offline/TC-01 古诗朗读后留下，再次打开使用本机缓存", async ({ page }) => {
    await page.goto(resolveURL("/gushi/"), { waitUntil: 'domcontentloaded' });
    await page.waitForTimeout(1500);
    await page.locator("#startBtn").first().click();
    await page.locator("#offlineHint").first().waitFor({ state: 'visible', timeout: 15000 });
    await page.goto(resolveURL("/gushi/#/p/1"), { waitUntil: 'domcontentloaded' });
    await page.waitForTimeout(1500);
    await page.locator("#offlineHint").first().waitFor({ state: 'visible', timeout: 15000 });
    await expect(page.locator("#offlineHint").first()).toContainText("正在使用本机缓存");
    expect(page.url()).toContain("#/p/1");
});
